import{_ as r,l as s,o as e,c as l,v as o,p as d,x as t,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"DDoS 缓解","description":"","frontmatter":{"title":"DDoS 缓解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ddos-mitigation.md","filePath":"cs/ddos-mitigation.md","lastUpdated":1789023840000}'),c={name:"cs/ddos-mitigation.md"};function m(D,a,_,B,E,f){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="ddos-缓解" tabindex="-1">DDoS 缓解 <a class="header-anchor" href="#ddos-缓解" aria-label="Permalink to &quot;DDoS 缓解&quot;">​</a></h1><div class="epigraph"><p>分布式拒绝服务用流量或连接耗尽容量。缓解是清洗、任播、过载降级与上游协作，不是在应用里再加一把锁。可用性与完整在此打架：宁可降级也不能把清洗做成永久中间人而不写进模型。</p><footer>—— 据 RFC 4732；Mirkovic and Reiher 对 DDoS 的分类；对照[DoS 与放大](/cs/dos-amplify)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/honeypot">蜜罐</a>观扫描。缺口是<strong>容量轴</strong>：主干放大课已有反射。本课收缓解：清洗中心、Anycast、挑战、弹性。不写如何发动 DDoS。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>带宽、状态表、应用线程都可被耗尽。缺口是分层：接入、ISP、CDN、应用过载保护。SYN 洪水与应用层洪水对策不同。</p><h3 id="放大" tabindex="-1">放大 <a class="header-anchor" href="#放大" aria-label="Permalink to &quot;放大&quot;">​</a></h3><p>开放解析器与 NTP 一类在主干已点名。缓解包括源头入站过滤（BCP 38）。</p><p><span class="marginnote">RFC 4732。禁止攻击指导。端口扫描下一课是侦察，不是洪水。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照容积与应用层。任播吸收、速率限制、降级静态页。指出 TLS 握手昂贵（密码学课已见）。</p>',12)),(e(),d(h,null,{default:t(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FLOOD%5B%22%E8%BF%87%E9%87%8F%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20SCRUB%5B%22%E6%B8%85%E6%B4%97%E6%88%96%E4%BB%BB%E6%92%AD%22%5D%0A%20%20FLOOD%20--%3E%20DEG%5B%22%E8%BF%87%E8%BD%BD%E9%99%8D%E7%BA%A7%22%5D%0A%20%20SRC%5B%22%E6%BA%90%E8%BF%87%E6%BB%A4%20BCP38%22%5D%20--%3E%20LESS%5B%22%E5%87%8F%E5%B0%91%E4%BC%AA%E9%80%A0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可用性是 CIA 的 A。清洗改变路径，要认证与合同，否则成中间人。扫描下一课是发现面，常是洪水的前奏。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写发动攻击。端口扫描与 Nmap 下一课：侦察方法论，防御视角。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蜜罐不解决容量；DDoS 要清洗与降级。</li><li>容积与应用层对策不同。</li><li>源过滤减少伪造放大。</li><li>下一课端口扫描。</li><li>出处：RFC 4732；Mirkovic and Reiher；BCP 38；<a href="/cs/dos-amplify">dos-amplify</a>。</li></ul>',8))])}const A=r(c,[["render",m]]);export{S as __pageData,A as default};
